@page "/dashboard"
@using sv_b11348da02674ece8588a0637eabdf42.Services
@rendermode InteractiveServer
@implements IDisposable
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @GetWarehouseName(WarehouseState.CurrentWarehouseId)
                </p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(AlertService.LowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">
                    Items below minimum stock level.
                    <br />Refreshes every 10 seconds.
                </p>
            </div>
        </div>
    </div>
</div>

<div class="alert alert-info">
    <strong>How it works:</strong> This page subscribes to polling on initialization and unsubscribes
    when you navigate away. The sidebar badge and this card both update simultaneously because they
    share the same scoped <code>InventoryAlertService</code> instance and listen to its
    <code>OnAlertDataChanged</code> event.
</div>

@code {
    protected override void OnInitialized()
    {
        AlertService.Subscribe();
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetWarehouseName(string id)
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.Unsubscribe();
    }
}

